/*
 * HTML 卡片统一样式（通用版）
 * 所有产出物共享同一份视觉基线，agent 生成时按 template.html 组装。
 * 修改前请阅读 references/design-rules.md 的 16 条硬规则。
 *
 * 换主色只改下面 3 个变量：--brand / --brand-deep / --brand-soft
 * 其余语义色（warn/ok/danger）建议保持，它们与规则 3/15 的语义绑定。
 */

:root {
  --brand: #0052D9;
  --brand-soft: #E8F0FE;
  --brand-deep: #003A99;
  --ink: #1F2329;
  --ink-2: #4E5969;
  --ink-3: #86909C;
  --line: #E5E6EB;
  --bg: #F7F8FA;
  --surface: #FFFFFF;
  --warn: #FF7D00;
  --warn-soft: #FFF7E8;
  --ok: #00B42A;
  --ok-soft: #E8FFEA;
  --danger: #F53F3F;
  --danger-soft: #FFECE8;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: 32px 20px;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
.container { max-width: 880px; margin: 0 auto; }

/* ========== 顶部 Banner ========== */
.banner {
  background: linear-gradient(135deg, var(--brand) 0%, var(--brand-deep) 100%);
  color: #fff;
  padding: 28px 32px;
  border-radius: 16px 16px 0 0;
  position: relative;
  overflow: hidden;
}
.banner::after {
  content: "";
  position: absolute;
  right: -40px; top: -40px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.06);
  border-radius: 50%;
}
/* Banner 顶部品牌+角色行（纯白小字，见规则 14/16；不需要品牌行可整段删除） */
.banner .brand-tag {
  font-size: 13px;
  color: rgba(255,255,255,0.85);
  margin: 0 0 10px 0;
  letter-spacing: 0.3px;
  position: relative;
  z-index: 1;
}
.banner .brand-tag .sep { margin: 0 6px; opacity: 0.6; }
/* Banner 左上角 logo + brand-tag 同行（垂直居中） */
.banner-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 10px 0;
  position: relative;
  z-index: 1;
}
.banner .banner-logo {
  display: block;
  width: 36px; height: 36px;
  border-radius: 8px;
  background: rgba(255,255,255,0.95);
  padding: 4px;
  flex-shrink: 0;
}
.banner-brand .brand-tag { margin: 0; }
.banner .title {
  font-size: 24px; font-weight: 600;
  margin: 0 0 4px 0;
}
.banner .subtitle {
  font-size: 14px; opacity: 0.9; margin: 0;
}
.banner .meta {
  margin-top: 14px; font-size: 13px;
  opacity: 0.85;
  display: flex; gap: 20px; flex-wrap: wrap;
}
.banner .meta span {
  display: inline-flex; align-items: center; gap: 6px;
}
.banner .meta i.bi {
  font-size: 14px; opacity: 0.9;
}

/* ========== 主体 ========== */
.body {
  background: var(--surface);
  padding: 28px 32px 8px;
  border-radius: 0 0 16px 16px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
}
section { margin-bottom: 28px; }
section:last-child { margin-bottom: 0; }

/* 章节大标题（h2）—— 序号 + 标题，无左竖条 */
h2.section-title {
  font-size: 17px; font-weight: 600;
  color: var(--ink);
  margin: 0 0 14px 0;
  line-height: 1.35;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
h2.section-title .idx {
  color: var(--brand);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.5px;
}

/* 每个模块的重点句 —— 放在模块正文之前；无固定前缀，见规则 2 */
.lead {
  font-size: 13.5px;
  color: var(--ink-2);
  line-height: 1.7;
  margin: 0 0 14px 0;
  padding: 12px 14px;
  background: #FAFBFC;
  border-radius: 6px;
}
.lead strong { color: var(--ink); font-weight: 600; }

/* ========== 表格（含 KV 型两列表；KV 型必须带 thead） ========== */
table.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}
table.data-table th {
  background: #FAFBFC;
  color: var(--ink-2);
  font-weight: 500;
  text-align: left;
  padding: 10px 12px;
  border-bottom: 2px solid var(--line);
  font-size: 13px;
}
table.data-table td {
  padding: 12px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
  color: var(--ink);
}
table.data-table tr:last-child td { border-bottom: none; }
table.data-table tr:hover td { background: #FAFBFC; }

/* KV 型表格：左列字段名（灰字 500 weight），右列内容。用 td.kv-key */
table.data-table td.kv-key {
  color: var(--ink-2);
  font-weight: 500;
}

/* 徽章 */
.pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
}
.pill-ok { background: var(--ok-soft); color: var(--ok); }
.pill-warn { background: var(--warn-soft); color: var(--warn); }
.pill-danger { background: var(--danger-soft); color: var(--danger); }
.pill-brand { background: var(--brand-soft); color: var(--brand); }
.pill-recommend { background: var(--brand); color: #fff; }

/* ========== 时间轴（精简版：每块 + 目标行 + 无 icon bullets） ========== */
.timeline {
  position: relative;
  padding-left: 24px;
}
.timeline::before {
  content: "";
  position: absolute;
  left: 6px; top: 8px; bottom: 8px;
  width: 2px; background: var(--line);
}
.tl-item { position: relative; padding-bottom: 20px; }
.tl-item:last-child { padding-bottom: 0; }
.tl-item::before {
  content: "";
  position: absolute;
  left: -22px; top: 7px;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--brand);
  border: 2px solid #fff;
  box-shadow: 0 0 0 2px var(--brand);
}
.tl-item .tl-head {
  font-size: 14px; font-weight: 600;
  color: var(--ink);
  margin-bottom: 4px;
  line-height: 1.4;
}
.tl-item .tl-head .week {
  color: var(--brand);
  margin-right: 6px;
}
.tl-item .tl-head .sep { color: var(--ink-3); margin: 0 4px; }
.tl-item .tl-goal {
  font-size: 13px;
  color: var(--ink-2);
  margin-bottom: 8px;
}
.tl-item .tl-goal strong { color: var(--ink); font-weight: 500; }
.tl-item .tl-list {
  margin: 0;
  padding-left: 20px;
  font-size: 13px;
  color: var(--ink-2);
  line-height: 1.85;
}
.tl-item .tl-list li { padding-left: 2px; }

/* ========== 提示条（2 色：默认蓝｜warn 黄，无 icon） ========== */
.callout {
  padding: 12px 16px;
  border-radius: 8px;
  border-left: 3px solid var(--brand);
  font-size: 13.5px;
  line-height: 1.7;
  background: var(--brand-soft);
  color: var(--ink);
  margin-top: 14px;
}
.callout strong.title {
  color: var(--brand-deep);
  font-weight: 600;
  margin-right: 4px;
}
.callout-warn { border-color: var(--warn); background: var(--warn-soft); color: #1F2329; }
.callout-warn strong.title { color: #7A4300; }

/* ========== 通用 bullet 列表 ==========
 * 高频用法：<li><strong>标签：</strong>描述文字</li>
 * 左标签深黑加粗 + 冒号后微空隙，扫读时锚点清晰
 */
ul.plain-list {
  margin: 0;
  padding-left: 20px;
  font-size: 13.5px;
  color: var(--ink-2);
  line-height: 1.85;
}
ul.plain-list li { margin: 4px 0; padding-left: 2px; }
ul.plain-list li strong { color: var(--ink); font-weight: 600; }
ul.plain-list li strong:first-child { margin-right: 4px; }

/* callout 内嵌 plain-list：紧贴上文的 title 行，无额外 margin */
.callout ul.plain-list { margin-top: 8px; color: inherit; }
.callout ul.plain-list li { color: inherit; }

/* ========== 决策标签（用于条件枚举 / 决策分支的结论词，无底色） ==========
 * 用法：<li><strong>若两点都谈成：</strong><span class="tag-ok">可接 ✓</span> 说明文字…</li>
 * 三档：ok（正向 / 推荐 / 可接）｜warn（谨慎 / 有条件 / 观望）｜bad（不推荐 / 不接 / 红线）
 * 关键：只染字色，不加底色。要与 plain-list 搭配使用，禁止塞进 callout。
 */
.tag-ok, .tag-warn, .tag-bad {
  font-weight: 600;
  margin-right: 4px;
}
.tag-ok { color: var(--ok); }
.tag-warn { color: var(--warn); }
.tag-bad { color: var(--danger); }

.disclaimer {
  text-align: center;
  font-size: 11.5px;
  color: var(--ink-3);
  margin-top: 20px;
  padding: 14px 0;
}

/* 打印友好 */
@media print {
  body { padding: 0; background: #fff; }
  .banner { border-radius: 0; }
  .body { border-radius: 0; box-shadow: none; }
}

